"""One redaction boundary for logs, audit payloads and error rendering."""

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any
from urllib.parse import parse_qsl, urlsplit, urlunsplit

REDACTED = "[REDACTED]"
_SENSITIVE_KEY = re.compile(r"(?:password|secret|pfx|key|token|cookie|authorization|xml|pdf)", re.I)
_SENSITIVE_QUERY = re.compile(r"(?:password|secret|token|key|cookie|authorization)", re.I)


def _redact_string(value: str) -> str:
    if (
        value.startswith("%PDF")
        or value.lstrip().startswith("<?xml")
        or value.lstrip().startswith("<")
    ):
        return REDACTED
    try:
        parsed = urlsplit(value)
    except ValueError:
        return value
    if not parsed.scheme or not parsed.netloc:
        return value
    if parsed.username or parsed.password:
        return REDACTED
    query = parse_qsl(parsed.query, keep_blank_values=True)
    if any(_SENSITIVE_QUERY.search(key) for key, _ in query):
        return urlunsplit((parsed.scheme, parsed.netloc, parsed.path, REDACTED, ""))
    return value


def redact(value: Any) -> Any:
    if isinstance(value, BaseException):
        # Exception arguments are arbitrary external data. Preserve only their
        # safe class; callers must not turn exception text into an output channel.
        return {"error_class": type(value).__name__}
    if isinstance(value, Mapping):
        return {
            str(key): REDACTED if _SENSITIVE_KEY.search(str(key)) else redact(item)
            for key, item in value.items()
        }
    if isinstance(value, tuple):
        return tuple(redact(item) for item in value)
    if isinstance(value, list):
        return [redact(item) for item in value]
    if isinstance(value, set):
        return {redact(item) for item in value}
    if isinstance(value, bytes):
        return REDACTED
    if isinstance(value, str):
        return _redact_string(value)
    return value
from __future__ import annotations

import hashlib
import hmac
import logging
import secrets
from dataclasses import dataclass
from datetime import timedelta

from django.conf import settings
from django.contrib.auth.hashers import check_password, make_password
from django.core.exceptions import ValidationError
from django.core.validators import validate_email
from django.db import IntegrityError, transaction
from django.utils import timezone

from nfx.audit.services import AuditService
from nfx.identity.models import IdentitySession, LoginThrottle, Role, User

logger = logging.getLogger(__name__)
SESSION_IDLE_TIMEOUT = timedelta(minutes=30)
BOOTSTRAP_ADMIN_EMAIL = "guilherme.duarte@inovssc.com.br"


@dataclass(frozen=True)
class SessionIdentity:
    user_id: str
    email: str
    name: str
    role: str


class UserAdministrationError(ValueError):
    pass


class UserVersionConflict(UserAdministrationError):
    pass


class DuplicateUserEmail(UserAdministrationError):
    pass


class LastAdministrator(UserAdministrationError):
    pass


def normalize_email(email: str) -> str:
    return email.strip().casefold()


def _validated_email(email: str) -> str:
    if not isinstance(email, str):
        raise UserAdministrationError("Invalid email")
    normalized = normalize_email(email)
    try:
        validate_email(normalized)
    except ValidationError as exc:
        raise UserAdministrationError("Invalid email") from exc
    return normalized


def _require_administrator(actor: SessionIdentity) -> None:
    if actor.role != Role.ADMINISTRATOR:
        raise UserAdministrationError("Administrator access required")


def _validated_reason(reason: str) -> str:
    if not isinstance(reason, str) or not reason.strip():
        raise UserAdministrationError("A reason is required")
    return reason.strip()


def _digest(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _subject_hash(email: str, ip_address: str) -> str:
    key = settings.SECRET_KEY.encode("utf-8")
    return hmac.new(
        key, f"{normalize_email(email)}\x00{ip_address}".encode(), hashlib.sha256
    ).hexdigest()


def _event(
    event: str,
    *,
    result: str,
    actor_id: str | None = None,
    actor_role: str = "",
    ip_address: str | None = None,
) -> None:
    """Authentication success is only visible after its append-only evidence persists."""
    AuditService().append(
        action=f"auth.{event}",
        entity_type="identity",
        entity_id=actor_id or "anonymous",
        result=result,
        actor_id=actor_id,
        actor_role=actor_role,
        ip_address=ip_address,
    )
    logger.info(
        "identity_event",
        extra={"event": event, "result": result, "actor_id": actor_id, "ip": ip_address},
    )


def bootstrap_first_administrator(password: str) -> tuple[User, bool]:
    """Create exactly the installation account, only while the user table is empty."""
    with transaction.atomic():
        if User.objects.exists():
            existing = User.objects.filter(email=BOOTSTRAP_ADMIN_EMAIL).first()
            if existing is None:
                raise RuntimeError("Bootstrap is only permitted on an empty user base")
            return existing, False
        user = User.objects.create(
            email=BOOTSTRAP_ADMIN_EMAIL,
            name="Guilherme Duarte",
            role=Role.ADMINISTRATOR,
            password_hash=make_password(password),
        )
        return user, True


def authenticate(
    email: str, password: str, ip_address: str, user_agent: str
) -> tuple[str | None, SessionIdentity | None]:
    """Return a token only for valid active accounts; every failure is intentionally uniform."""
    with transaction.atomic():
        now = timezone.now()
        subject_hash = _subject_hash(email, ip_address)
        throttle, _ = LoginThrottle.objects.get_or_create(
            subject_hash=subject_hash,
            defaults={"next_allowed_at": now},
        )
        if throttle.next_allowed_at > now:
            _event("login_failure", result="rate_limited", ip_address=ip_address)
            return None, None

        user = User.objects.filter(email=normalize_email(email)).first()
        valid = user is not None and user.active and check_password(password, user.password_hash)
        if not valid:
            failures = throttle.failures + 1
            delay = min(2 ** min(failures - 1, 8), 300)
            LoginThrottle.objects.filter(subject_hash=subject_hash).update(
                failures=failures, next_allowed_at=now + timedelta(seconds=delay)
            )
            _event("login_failure", result="denied", ip_address=ip_address)
            return None, None

        assert user is not None
        LoginThrottle.objects.filter(subject_hash=subject_hash).update(
            failures=0, next_allowed_at=now
        )
        token = secrets.token_urlsafe(32)
        IdentitySession.objects.create(
            token_hash=_digest(token),
            user=user,
            revocation_version=user.revocation_version,
            last_activity_at=now,
            expires_at=now + SESSION_IDLE_TIMEOUT,
            ip_address=ip_address or None,
            user_agent_hash=_digest(user_agent) if user_agent else "",
        )
        identity = SessionIdentity(str(user.id), user.email, user.name, user.role)
        _event(
            "login_success",
            result="success",
            actor_id=str(user.id),
            actor_role=user.role,
            ip_address=ip_address,
        )
        return token, identity


def resolve_session(token: str | None, *, touch: bool = True) -> SessionIdentity | None:
    if not token:
        return None
        return reclaimed, due

    def claim(self, owner: str) -> Job | None:
        if not owner or not owner.strip():
            raise ValueError("owner is required")
        now = self.clock()
        with transaction.atomic():
            Job.objects.filter(
                state=JobState.RUNNING,
                lease_expires_at__lte=now,
            ).update(
                state=JobState.QUEUED,
                scheduled_at=now,
                lease_owner=None,
                lease_issued_at=None,
                lease_expires_at=None,
                safe_error="lease_expired",
                updated_at=now,
            )
            job = (
                Job.objects.select_for_update(skip_locked=True)
                .filter(state=JobState.QUEUED, scheduled_at__lte=now)
                .order_by("-priority", "scheduled_at", "created_at")
                .first()
            )
            if job is None:
                return None
            job.state = JobState.RUNNING
            job.lease_owner = owner
            job.lease_issued_at = now
            job.lease_expires_at = now + self.lease_duration
            job.last_attempt_at = now
            job.attempt_count += 1
            job.updated_at = now
            job.save(
                update_fields=[
                    "state",
                    "lease_owner",
                    "lease_issued_at",
                    "lease_expires_at",
                    "last_attempt_at",
                    "attempt_count",
                    "updated_at",
                ]
            )
            return job

    def _lease_update(self, job_id: UUID | str, owner: str, **fields: Any) -> Job:
        now = self.clock()
        with transaction.atomic():
            updated = Job.objects.filter(
                id=job_id,
                state=JobState.RUNNING,
                lease_owner=owner,
                lease_expires_at__gt=now,
            ).update(**fields, updated_at=now)
            if not updated:
                if Job.objects.filter(id=job_id, state=JobState.RUNNING).exists():
                    raise LeaseLost("job lease is no longer valid")
                raise InvalidTransition("job is not running")
            return Job.objects.get(id=job_id)

    def renew(self, job_id: UUID | str, owner: str) -> Job:
        now = self.clock()
        return self._lease_update(
            job_id,
            owner,
            lease_expires_at=now + self.lease_duration,
        )

    def complete(
        self, job_id: UUID | str, owner: str, result: Mapping[str, Any] | None = None
    ) -> Job:
        safe_result = _validate_safe_value(result or {}, path="result")
        now = self.clock()
        return self._lease_update(
            job_id,
            owner,
            state=JobState.COMPLETED,
            lease_owner=None,
            lease_issued_at=None,
            lease_expires_at=None,
            safe_result=safe_result,
            safe_error="",
            completed_at=now,
            last_outcome=JobOutcomeKind.SUCCESS,
            cooldown_until=None,
            blocked_at=None,
            blocked_reason="",
        )

"""Explicit handler boundary used by the worker and synthetic tests."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any

from nfx.jobs.models import Job, JobOutcomeKind


@dataclass(frozen=True)
class HandlerOutcome:
    """Safe, classified result returned by a registered handler."""

    kind: str
    result: Mapping[str, Any] = field(default_factory=dict)
    error_code: str = ""
    cooldown_until: datetime | None = None

    @classmethod
    def success(cls, result: Mapping[str, Any] | None = None) -> HandlerOutcome:
        return cls(JobOutcomeKind.SUCCESS, result or {})

    @classmethod
    def temporary(
        cls, *, error_code: str = "temporary_failure", result: Mapping[str, Any] | None = None
    ) -> HandlerOutcome:
        return cls(JobOutcomeKind.TEMPORARY, result or {}, error_code)

    @classmethod
    def cooldown(
        cls,
        *,
        cooldown_until: datetime | None = None,
        error_code: str = "official_cooldown",
        result: Mapping[str, Any] | None = None,
    ) -> HandlerOutcome:
        return cls(JobOutcomeKind.COOLDOWN, result or {}, error_code, cooldown_until)

    @classmethod
    def permanent(
        cls, *, error_code: str = "permanent_failure", result: Mapping[str, Any] | None = None
    ) -> HandlerOutcome:
        return cls(JobOutcomeKind.PERMANENT, result or {}, error_code)

    @classmethod
    def partial(
        cls, *, error_code: str = "partial_failure", result: Mapping[str, Any] | None = None
    ) -> HandlerOutcome:
        return cls(JobOutcomeKind.PARTIAL, result or {}, error_code)


JobOutcome = HandlerOutcome
JobHandler = Callable[[Job], HandlerOutcome | Mapping[str, Any] | None]
_HANDLERS: dict[str, JobHandler] = {}


def register_handler(job_type: str, handler: JobHandler) -> None:
    if not job_type or not job_type.strip():
        raise ValueError("job_type is required")
    _HANDLERS[job_type] = handler


def unregister_handler(job_type: str) -> None:
    _HANDLERS.pop(job_type, None)


def clear_handlers() -> None:
    _HANDLERS.clear()


def get_handler(job_type: str) -> JobHandler | None:
    return _HANDLERS.get(job_type)

from __future__ import annotations

import json
from collections.abc import Callable
from uuid import UUID

from django.http import HttpRequest, HttpResponse, JsonResponse
from django.views.decorators.csrf import ensure_csrf_cookie
from django.views.decorators.http import require_GET, require_http_methods, require_POST

from nfx.identity.policy import Action
from nfx.identity.services import (
    DuplicateUserEmail,
    LastAdministrator,
    UserAdministrationError,
    UserVersionConflict,
    authenticate,
    change_own_password,
    change_user_role,
    create_user,
    require_authorized,
    reset_user_password,
    resolve_session,
    revoke_session,
    set_user_active,
    update_user,
)

SESSION_COOKIE_NAME = "nfx_session"
INVALID_CREDENTIALS = {"detail": "Credenciais inválidas."}


def _json_body(request: HttpRequest) -> dict[str, object] | None:
    try:
        body = json.loads(request.body)
    except (TypeError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    return body if isinstance(body, dict) else None


def _request_ip(request: HttpRequest) -> str:
    return str(request.META.get("REMOTE_ADDR", ""))


def _user_payload(user: object) -> dict[str, object]:
    from nfx.identity.models import User

    assert isinstance(user, User)
    return {
        "id": str(user.id),
        "name": user.name,
        "email": user.email,
        "role": user.role,
        "active": user.active,
        "version": user.version,
    }


def _integer(body: dict[str, object], name: str) -> int | None:
    value = body.get(name)
    return value if isinstance(value, int) and value > 0 else None


def _admin_error(exc: Exception) -> JsonResponse:
    if isinstance(exc, DuplicateUserEmail):
        return JsonResponse({"detail": "E-mail já cadastrado."}, status=409)
    if isinstance(exc, UserVersionConflict):
        return JsonResponse({"detail": "Usuário alterado por outra solicitação."}, status=409)
    if isinstance(exc, LastAdministrator):
        return JsonResponse({"detail": "É necessário manter um Administrador ativo."}, status=409)
    return JsonResponse({"detail": "Não foi possível concluir a operação."}, status=400)


@require_GET
@ensure_csrf_cookie
def csrf(_: HttpRequest) -> JsonResponse:
    return JsonResponse({"detail": "CSRF pronto."})


@require_POST
def login(request: HttpRequest) -> JsonResponse:
    body = _json_body(request)
    email = body.get("email") if body else None
    password = body.get("password") if body else None
    if not isinstance(email, str) or not isinstance(password, str):
        return JsonResponse(INVALID_CREDENTIALS, status=401)
    token, identity = authenticate(
        email, password, _request_ip(request), request.headers.get("User-Agent", "")
    )
    if token is None or identity is None:
        return JsonResponse(INVALID_CREDENTIALS, status=401)
    response = JsonResponse(
        {"user": {"id": identity.user_id, "name": identity.name, "role": identity.role}}
    )
    response.set_cookie(
        SESSION_COOKIE_NAME, token, secure=True, httponly=True, samesite="Lax", path="/api/"
    )
    response["Cache-Control"] = "no-store"
    return response


@require_POST
def logout(request: HttpRequest) -> JsonResponse:
    revoke_session(request.COOKIES.get(SESSION_COOKIE_NAME))
    response = JsonResponse({"detail": "Sessão encerrada."})
    response.delete_cookie(SESSION_COOKIE_NAME, path="/api/", samesite="Lax")
    response["Cache-Control"] = "no-store"
    return response


@require_GET
def session(request: HttpRequest) -> JsonResponse:
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME))
    if identity is None:
        return JsonResponse({"detail": "Não autenticado."}, status=401)
    response = JsonResponse(
        {"user": {"id": identity.user_id, "name": identity.name, "role": identity.role}}
    )
    response["Cache-Control"] = "no-store"
    return response


def protected(
    action: Action, *, owner_id: Callable[[HttpRequest], str | None] | None = None
) -> Callable[[Callable[..., HttpResponse]], Callable[..., HttpResponse]]:
    def decorator(view: Callable[..., HttpResponse]) -> Callable[..., HttpResponse]:
        def wrapped(request: HttpRequest, *args: object, **kwargs: object) -> HttpResponse:
            identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME))
            if not require_authorized(
                identity, action.value, owner_id(request) if owner_id else None
            ):
                return JsonResponse({"detail": "Acesso negado."}, status=403)
            return view(request, *args, **kwargs)

        return wrapped

    return decorator


@require_GET
@protected(Action.ADMINISTER_USERS)
def users(request: HttpRequest) -> JsonResponse:
    from nfx.identity.models import Role, User

    active = request.GET.get("active")
    role = request.GET.get("role")
    try:
        limit = min(max(int(request.GET.get("limit", "50")), 1), 100)
        cursor = request.GET.get("cursor", "")
    except ValueError:
        return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
    queryset = User.objects.order_by("id")
    if active not in {None, "true", "false"}:
        return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
    if active in {"true", "false"}:
        queryset = queryset.filter(active=active == "true")
    if role:
        if role not in Role.values:
            return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
        queryset = queryset.filter(role=role)
    if cursor:
        try:
            cursor_id = UUID(cursor)
        except ValueError:
            return JsonResponse({"detail": "Parâmetros inválidos."}, status=400)
        queryset = queryset.filter(id__gt=cursor_id)
    rows = list(queryset[: limit + 1])
    return JsonResponse(
        {
            "users": [_user_payload(row) for row in rows[:limit]],
            "next_cursor": str(rows[limit].id) if len(rows) > limit else None,
        }
    )


@require_POST
@protected(Action.ADMINISTER_USERS)
def user_create(request: HttpRequest) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    if body is None or identity is None:
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    required = ("name", "email", "role", "password")
    if any(not isinstance(body.get(field), str) for field in required):
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        user = create_user(
            actor=identity,
            name=str(body["name"]),
            email=str(body["email"]),
            role=str(body["role"]),
            password=str(body["password"]),
            ip_address=_request_ip(request),
        )
    except UserAdministrationError as exc:
        return _admin_error(exc)
    return JsonResponse({"user": _user_payload(user)}, status=201)


@require_http_methods(["PATCH"])
@protected(Action.ADMINISTER_USERS)
def user_update(request: HttpRequest, user_id: str) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    version = _integer(body or {}, "version")
    if (
        body is None
        or identity is None
        or version is None
        or not isinstance(body.get("name"), str)
        or not isinstance(body.get("email"), str)
    ):
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        user = update_user(
            actor=identity,
            user_id=user_id,
            version=version,
            name=str(body["name"]),
            email=str(body["email"]),
            ip_address=_request_ip(request),
        )
    except (UserAdministrationError, ValueError) as exc:
        return _admin_error(exc)
    return JsonResponse({"user": _user_payload(user)})


def _admin_action(request: HttpRequest, user_id: str, operation: str) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    version = _integer(body or {}, "version")
    reason = body.get("reason") if body else None
    reason_value = reason if isinstance(reason, str) else ""
    if body is None or identity is None or version is None:
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        if operation == "role":
            role = body.get("role")
            if not isinstance(role, str):
                raise UserAdministrationError("Invalid role")
            user = change_user_role(
                actor=identity,
                user_id=user_id,
                version=version,
                role=role,
                reason=reason_value,
                ip_address=_request_ip(request),
            )
        elif operation == "password":
            password = body.get("password")
            if not isinstance(password, str):
                raise UserAdministrationError("Invalid password")
            user = reset_user_password(
                actor=identity,
                user_id=user_id,
                version=version,
                password=password,
                reason=reason_value,
                ip_address=_request_ip(request),
            )
        else:
            active = body.get("active")
            if not isinstance(active, bool) or (not active and not isinstance(reason, str)):
                raise UserAdministrationError("Invalid state")
            user = set_user_active(
                actor=identity,
                user_id=user_id,
                version=version,
                active=active,
                reason=reason if isinstance(reason, str) else "",
                ip_address=_request_ip(request),
            )
    except (UserAdministrationError, ValueError) as exc:
        return _admin_error(exc)
    return JsonResponse({"user": _user_payload(user)})


@require_POST
@protected(Action.ADMINISTER_USERS)
def user_role(request: HttpRequest, user_id: str) -> JsonResponse:
    return _admin_action(request, user_id, "role")


@require_POST
@protected(Action.ADMINISTER_USERS)
def user_password_reset(request: HttpRequest, user_id: str) -> JsonResponse:
    return _admin_action(request, user_id, "password")


@require_POST
@protected(Action.CHANGE_OWN_PASSWORD)
def user_password_change(request: HttpRequest) -> JsonResponse:
    body = _json_body(request)
    identity = resolve_session(request.COOKIES.get(SESSION_COOKIE_NAME), touch=False)
    current_password = body.get("current_password") if body else None
    password = body.get("password") if body else None
    if identity is None or not isinstance(current_password, str) or not isinstance(password, str):
        return JsonResponse({"detail": "Dados inválidos."}, status=400)
    try:
        change_own_password(
            actor=identity,
            current_password=current_password,
            password=password,
            ip_address=_request_ip(request),
        )
    except UserAdministrationError:
        return JsonResponse({"detail": "Não foi possível alterar a senha."}, status=400)
    return JsonResponse({"detail": "Senha alterada."})


@require_POST
@protected(Action.ADMINISTER_USERS)
def user_active(request: HttpRequest, user_id: str) -> JsonResponse:
    return _admin_action(request, user_id, "active")
